sys_script.script:
/**
 * 23-Enforce booking cutoff
 *
 * Aborts a reservation when the start date is in the past, or when the booking
 * was placed after the cutoff time configured on that calendar day.
 * Reception staff and admins may still book after the cutoff.
 */
(function executeRule(current, previous) {
    if (!current.isNewRecord() && !current.start_date.changes()) {
        return;
    }

    var startDate = current.getValue('start_date');
    if (!startDate) {
        return;
    }

    var today = new GlideDateTime(gs.beginningOfToday());
    var start = new GlideDateTime(startDate);
    if (start.getValue() < today.getValue()) {
        gs.addErrorMessage('Bookings cannot start in the past. Choose ' + gs.dateFormat(today, 'yyyy-MM-dd') + ' or later.');
        current.setAbortAction(true);
        return;
    }

    var calDay = new GlideRecord('x_2203703_car_re_0_cal_day');
    calDay.addQuery('date', '=', gs.dateFormat(start, 'yyyy-MM-dd'));
    calDay.query();
    if (!calDay.next()) {
        return; // not on the calendar: the business-day rule reports it
    }

    var cutoff = calDay.getValue('cutoff_time');
    if (!cutoff) {
        return;
    }

    var roles = gs.getUser().getRoles();
    for (var i = 0; i < roles.length; i++) {
        if (roles[i] == 'x_2203703_car_re_0.receptionist' || roles[i] == 'x_2203703_car_re_0.admin') {
            return; // staff may book after the cutoff
        }
    }

    var closeAt = new GlideDateTime(startDate + ' ' + cutoff);
    if (new GlideDateTime().getValue() >= closeAt.getValue()) {
        gs.addErrorMessage('Bookings for ' + gs.dateFormat(start, 'yyyy-MM-dd') + ' closed at ' + cutoff + '. Please choose a later business day.');
        current.setAbortAction(true);
    }
})(current, previous);
